#!/usr/bin/env bash
# The terminal sessions quoted in lesson 24 of azure-operations, as a script that
# produces them. Its output is not committed; every transcript was copied from it.
#
#   bash lab.sh student && bash lab.sh tools   # once
#   bash captures.sh
#
# CostDaily is generated by the lesson's cost.kql, sixty days of fourteen
# resources at round illustrative daily costs, and says so; it is not a
# Cost Management export. The Bicep policies are compiled, never assigned.

HERE=$(cd "$(dirname "$0")" && pwd)
# shellcheck source=../../capture.sh
. "$HERE/../../capture.sh"
student_env
mkdir -p "$HOME/azure/tags" && cd "$HOME/azure/tags" || exit 1

put tag-policies.bicep <<'BICEP'
// tag-policies.bicep
targetScope = 'subscription'

resource requireTeam 'Microsoft.Authorization/policyDefinitions@2023-04-01' = {
  name: 'require-team-tag-on-groups'
  properties: {
    displayName: 'Resource groups must carry a team tag'
    policyType: 'Custom'
    mode: 'All'
    policyRule: {
      if: {
        allOf: [
          { field: 'type', equals: 'Microsoft.Resources/subscriptions/resourceGroups' }
          { field: 'tags[\'team\']', exists: 'false' }
        ]
      }
      then: { effect: 'deny' }
    }
  }
}

resource inheritTeam 'Microsoft.Authorization/policyDefinitions@2023-04-01' = {
  name: 'inherit-team-tag'
  properties: {
    displayName: 'Resources inherit the team tag from their resource group'
    policyType: 'Custom'
    mode: 'Indexed'
    policyRule: {
      if: {
        allOf: [
          { field: 'tags[\'team\']', exists: 'false' }
          { value: '[resourceGroup().tags[\'team\']]', notEquals: '' }
        ]
      }
      then: {
        effect: 'modify'
        details: {
          roleDefinitionIds: [ '/providers/Microsoft.Authorization/roleDefinitions/b24988ac-6180-42a0-ab88-20f7382dd24c' ]
          operations: [
            { operation: 'add', field: 'tags[\'team\']', value: '[resourceGroup().tags[\'team\']]' }
          ]
        }
      }
    }
  }
}
BICEP

block policies
run 'bicep build tag-policies.bicep; echo "exit status $?"'
run "jq -r '.resources[] | [.name, .properties.policyRule.then.effect] | @tsv' tag-policies.json"

kusto_up && kusto_db
kusto_load le-bwn2ccbr/cost-export.md:cost.kql
cd "$HOME/azure/kusto" || exit 1

block by-team
kq 'CostDaily | where Date >= datetime(2026-09-19) | summarize cost = round(sum(Cost), 2) by team = tostring(Tags.team) | order by cost desc'

put nobody.kql <<'KQL'
// nobody.kql: thirty days of spend with no team tag, by resource
CostDaily
| where Date >= datetime(2026-09-19)
| where isempty(tostring(Tags.team))
| summarize cost = round(sum(Cost), 2) by ResourceGroup, ResourceName, MeterCategory
| order by cost desc
KQL
block nobody
run 'python3 kql.py < nobody.kql'
block share
kq 'CostDaily | where Date >= datetime(2026-09-19) | summarize total = sum(Cost), untagged = sumif(Cost, isempty(tostring(Tags.team))) | extend untagged_pct = round(100.0 * untagged / total, 1), total = round(total, 2), untagged = round(untagged, 2)'
lab_down
